-- Mirrors data-dictionary.yaml (queryable via pg_description).
COMMENT ON TABLE garage IS 'A physical garage whose spots can be reserved. Seeded/managed outside this API.';
COMMENT ON COLUMN garage.garage_id IS 'Surrogate key, internal.';
COMMENT ON COLUMN garage.code IS 'Stable external garage code used by clients and events, e.g. ''HBF-01''. Unique.';
COMMENT ON COLUMN garage.name IS 'Human-readable garage name for staff.';
COMMENT ON COLUMN garage.time_zone IS 'IANA time zone name, e.g. ''Europe/Zurich''; defines the calendar day for staff lookups (R18).';
COMMENT ON COLUMN garage.created_at IS 'Row creation instant.';
COMMENT ON COLUMN garage.updated_at IS 'Last update instant, set by the writing process''s clock (backend, or the seeding process for garage and spot).';
COMMENT ON TABLE spot IS 'A single parking spot in a garage; the unit that is never double-booked.';
COMMENT ON COLUMN spot.spot_id IS 'Surrogate key, internal.';
COMMENT ON COLUMN spot.garage_id IS 'Owning garage.';
COMMENT ON COLUMN spot.label IS 'Spot label unique within its garage, e.g. ''A12''. Free-spot assignment picks the first label in byte order (collation C), so ''A10'' precedes ''A2''.';
COMMENT ON COLUMN spot.created_at IS 'Row creation instant.';
COMMENT ON COLUMN spot.updated_at IS 'Last update instant, set by the writing process''s clock (backend, or the seeding process for garage and spot).';
COMMENT ON TABLE reservation IS 'A driver''s claim on one spot for a half-open time window [start_at, end_at); moves reserved -> checked_in -> completed, or reserved -> cancelled.';
COMMENT ON COLUMN reservation.reservation_id IS 'Surrogate key, internal only; never exposed.';
COMMENT ON COLUMN reservation.public_id IS 'Externally visible reservation reference (a UUID, version 7) generated by the backend; given one, neighbours cannot be derived.';
COMMENT ON COLUMN reservation.garage_id IS 'Garage of the reserved spot; kept consistent with the spot by a composite foreign key.';
COMMENT ON COLUMN reservation.spot_id IS 'The spot assigned to this reservation.';
COMMENT ON COLUMN reservation.driver_id IS 'Opaque driver identifier from the identity provider; no other personal data is stored.';
COMMENT ON COLUMN reservation.idempotency_key IS 'Client-supplied retry key for the create call, unique per driver.';
COMMENT ON COLUMN reservation.start_at IS 'Inclusive start of the reserved window.';
COMMENT ON COLUMN reservation.end_at IS 'Exclusive end of the reserved window; strictly after start_at.';
COMMENT ON COLUMN reservation.status IS 'Lifecycle state: reserved, checked_in, completed, cancelled. All but cancelled hold the window.';
COMMENT ON COLUMN reservation.checked_in_at IS 'Instant of check-in; set exactly when status is checked_in or completed.';
COMMENT ON COLUMN reservation.checked_out_at IS 'Instant of check-out; set exactly when status is completed.';
COMMENT ON COLUMN reservation.cancelled_at IS 'Instant of cancellation; set exactly when status is cancelled.';
COMMENT ON COLUMN reservation.created_at IS 'Row creation instant.';
COMMENT ON COLUMN reservation.updated_at IS 'Last update instant, set by the writing process''s clock (backend, or the seeding process for garage and spot).';
COMMENT ON TABLE outbox_event IS 'Lifecycle event written in the same transaction as the reservation change, published later by the relay (at-least-once).';
COMMENT ON COLUMN outbox_event.event_id IS 'Event identity (a UUID, version 7) generated by the backend; the dedup id for consumers such as billing.';
COMMENT ON COLUMN outbox_event.topic IS 'Destination topic name, e.g. ''parking-reservation-completed-v1''.';
COMMENT ON COLUMN outbox_event.reservation_id IS 'Reservation the event describes (internal key).';
COMMENT ON COLUMN outbox_event.payload IS 'Complete event body as published, built by reservation_event_payload at write time. Fields: event_id (this row''s key), topic (this row''s topic), occurred_at (writer''s clock at the transition), reservation_public_id (reservation.public_id), status, driver_id, start_at, end_at, checked_in_at, checked_out_at, cancelled_at (reservation columns of the same names), garage_code (garage.code), spot_label (spot.label).';
COMMENT ON COLUMN outbox_event.status IS 'pending (awaiting publish), published, or parked (gave up after repeated failures; needs an operator).';
COMMENT ON COLUMN outbox_event.attempts IS 'Failed publish attempts so far.';
COMMENT ON COLUMN outbox_event.last_error IS 'Error text of the latest failed attempt; null if none.';
COMMENT ON COLUMN outbox_event.published_at IS 'Instant the broker acknowledged the publish; set exactly when status is published.';
COMMENT ON COLUMN outbox_event.created_at IS 'Row creation instant.';
COMMENT ON COLUMN outbox_event.updated_at IS 'Last update instant, set by the writing process''s clock (backend, or the seeding process for garage and spot).';
COMMENT ON TABLE schema_migration IS 'Technical table recording which migration files have been applied.';
COMMENT ON COLUMN schema_migration.version IS 'Migration file name that has been applied.';
COMMENT ON COLUMN schema_migration.created_at IS 'Instant the migration was applied.';
